# -*- coding: utf-8 -*-
#!/usr/bin/env python3
import base64, hashlib, io, runpy, sys, tempfile, zipfile, os
from pathlib import Path
ARCHIVE=base64.b64decode('')
SHA256='47b0fa814ad6e2ae0da4875e861184463eccca6724e02729fe6890d6a81c5069'
if hashlib.sha256(ARCHIVE).hexdigest()!=SHA256: raise SystemExit("QV package integrity failure")
root=Path(tempfile.gettempdir())/("QV_Legendary_Master_"+SHA256[:16]); root.mkdir(parents=True,exist_ok=True)
marker=root/'.extracted'
if not marker.exists():
    with zipfile.ZipFile(io.BytesIO(ARCHIVE),'r') as zz: zz.extractall(root)
    marker.write_text(SHA256,encoding='utf-8')
entry=root/'qv57'/'Nafezu.py'
if not entry.exists(): raise SystemExit("QV entrypoint not found")
os.chdir(entry.parent); sys.path.insert(0,str(entry.parent)); runpy.run_path(str(entry),run_name='__main__')
